<script>
    const fishes = document.querySelectorAll('.fish');
    const fishBehaviorRecords = new Map();

    fishes.forEach(fish => {
        let speed = 1 + Math.random() * 2;
        let directionX = Math.random() < 0.5 ? -1 : 1;
        let directionY = Math.random() < 0.5 ? -1 : 1;
