        fish.style.transform = `scaleX(${facingRight ? '-1' : '1'})`;

        fishBehaviorRecords.set(fish, { previousCollisions: 0, lastCheck: Date.now() });

        function checkCollision(fishRect, otherFishRect) {
            return !(fishRect.right < otherFishRect.left || 
