                     fishRect.bottom < otherFishRect.top || 
                     fishRect.top > otherFishRect.bottom);
        }

        function moveFish() {
            const roomRect = fish.parentElement.getBoundingClientRect();
            const fishRect = fish.getBoundingClientRect();
            let collision = false;
            const behavior = fishBehaviorRecords.get(fish);
            const now = Date.now();

            // Calculate next position
            let nextLeft = fish.offsetLeft + directionX * speed;
            let nextTop = fish.offsetTop + directionY * speed;

