                    directionX *= -1;
                    directionY *= -1;
                    facingRight = !facingRight;
                    fish.style.transform = `scaleX(${facingRight ? '-1' : '1'})`;
                    collision = true;
                    behavior.previousCollisions += 1;
                }
            });

            // Random Surrogate Conscious Behavior (RSCB) and Anti-Swarming Escapism (ASE)
            if (!collision && Math.random() < 0.01) {
                directionX *= -1;
                directionY *= -1;
                facingRight = !facingRight;
                fish.style.transform = `scaleX(${facingRight ? '-1' : '1'})`;
                speed = 1 + Math.random() * 2;
