import java.util.Arrays;

public class SawtoothImage {
    private BufferedImage image;
    private int lowerThreshold;
    private int upperThreshold;

    public SawtoothImage(BufferedImage image, int lowerThreshold, int upperThreshold) {
        this.image = image;
        this.lowerThreshold = lowerThreshold;
        this.upperThreshold = upperThreshold;
    }

    private void generateSawtoothImage() {
        if (image != null) {
            // Пилообразное контрастирование
            BufferedImage sawtoothContrastImage = sawtoothContrast(image, lowerThreshold, upperThreshold);

            // Сохраняем изображения
            setImageIcon(sawtoothContrastImage);
            saveImage(sawtoothContrastImage);

            // Создаем гистограммы
            createHistogram(image, "Гистограмма исходного изображения", false);
            createHistogram(sawtoothContrastImage, "Гистограмма пилообразного контраста", true);
        }
    }

    private BufferedImage sawtoothContrast(BufferedImage image, int lowerThreshold, int upperThreshold) {
        BufferedImage sawtoothContrastImage = new BufferedImage(image.getWidth(), image.getHeight(),
                BufferedImage.TYPE_INT_RGB);

        for (int i = 0; i < image.getWidth(); i++) {
            for (int j = 0; j < image.getHeight(); j++) {
                int rgb = image.getRGB(i, j);
                int r = (rgb >> 16) & 0xff;
                int g = (rgb >> 8) & 0xff;
                int b = rgb & 0xff;

                // Применяем пилообразное контрастирование
                int newR = applySawtooth(r, lowerThreshold, upperThreshold);
                int newG = applySawtooth(g, lowerThreshold, upperThreshold);
                int newB = applySawtooth(b, lowerThreshold, upperThreshold);

                int newRGB = (newR << 16) | (newG << 8) | newB;
                sawtoothContrastImage.setRGB(i, j, newRGB);
            }
        }
        return sawtoothContrastImage;
    }

    private int applySawtooth(int value, int lowerThreshold, int upperThreshold) {
        if (value < lowerThreshold) {
            return 0;
        } else if (value > upperThreshold) {
            return 255;
        } else {
            return (int) ((double) (value - lowerThreshold) / (upperThreshold - lowerThreshold) * 255);
        }
    }

    private void createHistogram(BufferedImage image, String title, boolean scalable) {
        int[] histogram = new int[256];
        Arrays.fill(histogram, 0);

        for (int i = 0; i < image.getWidth(); i++) {
            for (int j = 0; j < image.getHeight(); j++) {
                int pixel = image.getRGB(i, j);
                int red = (pixel >> 16) & 0xff;
                int green = (pixel >> 8) & 0xff;
                int blue = pixel & 0xff;
                // Вычисляем яркость пикселя
                int brightness = (int) (0.2126 * red + 0.7152 * green + 0.0722 * blue);
                histogram[brightness]++;
            }
        }

        JFrame histogramFrame = new JFrame(title);
        histogramFrame.setLayout(new FlowLayout(FlowLayout.CENTER, 10, 10));

        JPanel histogramPanel = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                super.paintComponent(g);
                int max = Arrays.stream(histogram).max().getAsInt();
                for (int i = 0; i < 256; i++) {
                    int height = (int) (getHeight() * histogram[i] / (double) max);
                    g.fillRect(i, getHeight() - height, 1, height);
                }
            }
        };

        int panelHeight = scalable ? 600 : 300;
        histogramPanel.setPreferredSize(new Dimension(256, panelHeight));

        histogramFrame.add(new JLabel(title));
        histogramFrame.add(histogramPanel);
        histogramFrame.pack();
        histogramFrame.setLocationRelativeTo(null);
        histogramFrame.setVisible(true);
    }

    private void setImageIcon(BufferedImage image) {
        // Реализуйте отображение изображения
    }

    private void saveImage(BufferedImage image) {
        // Реализуйте сохранение изображения
    }

    public static void main(String[] args) {
        // Загрузка изображения и вызов метода генерации пилообразного изображения
    }
}
```

