import React, { createContext, useState } from 'react';

interface NotificationContextProps {
  notifications: {
    wind: boolean,
    rain: boolean
  };
  toggleNotification: (type: 'wind' | 'rain') => void;
}

const defaultContext = {
  notifications: { wind: false, rain: false },
  toggleNotification: () => {}
};

export const NotificationContext = createContext<NotificationContextProps>(defaultContext);

const NotificationProvider: React.FC = ({ children }) => {
  const [notifications, setNotifications] = useState({ wind: false, rain: false });

  const toggleNotification = (type: 'wind' | 'rain') => {
    setNotifications((prev) => ({ ...prev, [type]: !prev[type] }));
  };

  return (
    <NotificationContext.Provider value={{ notifications, toggleNotification }}>
      {children}
    </NotificationContext.Provider>
  );
};

export default NotificationProvider;
```

