Developing a full-fledged mini compiler that can interpret and execute pseudo code involves several key steps. Here, I will outline and implement a basic version that includes a parser, an interpreter, and support for fundamental programming constructs. This example will be simplified and written in Python for educational purposes. The pseudo code will support basic control structures, expressions, and variables.

### Step 1: Define the Language Grammar

Before we start coding, let's define the pseudo code grammar we'll support. Here's a simple grammar:

1. **Variables**: Variable names start with a lowercase letter.
2. **Assignment**: Syntax: `variable = expression`
3. **Expressions**: Can include integers, mathematical operations (`+`, `-`, `*`, `/`), and other variables.
4. **Control Structures**: 
   - `if expression then statements else statements end`
   - `while expression do statements end`
   - `print expression`
5. **Statements**: Each statement ends with a newline.

### Step 2: Develop the Tokenizer

A tokenizer breaks down the input pseudo code into tokens.

```python
import re

class Tokenizer:
    def __init__(self, code):
        self.tokens = []
        self.current_pos = 0
        self.token_patterns = [
            ('NUMBER', r'\b\d+\b'),
            ('IDENTIFIER', r'\b[a-z]\b'),
            ('ASSIGN', r'='),
            ('PLUS', r'\+'),
            ('MINUS', r'-'),
            ('MULTIPLY', r'\*'),
            ('DIVIDE', r'/'),
            ('IF', r'\bif\b'),
            ('THEN', r'\bthen\b'),
            ('ELSE', r'\belse\b'),
            ('END', r'\bend\b'),
            ('WHILE', r'\bwhile\b'),
            ('DO', r'\bdo\b'),
            ('PRINT', r'\bprint\b'),
            ('LPAREN', r'\('),
            ('RPAREN', r'\)'),
            ('NEWLINE', r'\n'),
            ('WHITESPACE', r'[ \t]+'),
        ]
        self.tokenize(code)

    def tokenize(self, code):
        patterns = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in self.token_patterns)
        regex = re.compile(patterns)
        line_number = 1
        for mo in regex.finditer(code):
            kind = mo.lastgroup
            value = mo.group()
            if kind == 'WHITESPACE':
                continue
            if kind == 'NEWLINE':
                line_number += 1
            self.tokens.append((kind, value, line_number))

    def next_token(self):
        if self.current_pos >= len(self.tokens):
            return None
        token = self.tokens[self.current_pos]
        self.current_pos += 1
        return token

    def peek_token(self, lookahead=1):
        pos = self.current_pos + lookahead - 1
        if pos >= len(self.tokens):
            return None
        return self.tokens[pos]

    def expect_token(self, expected_kind):
        token = self.next_token()
        if not token:
            raise SyntaxError(f"Expected {expected_kind} but got EOF")
        kind, value, line = token
        if kind != expected_kind:
            raise SyntaxError(f"Expected {expected_kind} but got {kind} '{value}' at line {line}")
        return token

    def rewind(self):
        if self.current_pos > 0:
            self.current_pos -= 1
```

### Step 3: Develop the Parser

The parser converts the token stream into an Abstract Syntax Tree (AST).

```python
class ASTNode:
    pass

class NumberNode(ASTNode):
    def __init__(self, value):
        self.value = value

class VariableNode(ASTNode):
    def __init__(self, name):
        self.name = name

class BinaryOpNode(ASTNode):
    def __init__(self, left, op, right):
        self.left = left
        self.op = op
        self.right = right

class AssignNode(ASTNode):
    def __init__(self, variable, expression):
        self.variable = variable
        self.expression = expression

class PrintNode(ASTNode):
    def __init__(self, expression):
        self.expression = expression

class IfNode(ASTNode):
    def __init__(self, condition, then_body, else_body):
        self.condition = condition
        self.then_body = then_body
        self.else_body = else_body

class WhileNode(ASTNode):
    def __init__(self, condition, body):
        self.condition = condition
        self.body = body

class Parser:
    def __init__(self, tokenizer):
        self.tokenizer = tokenizer

    def parse(self):
        return self.parse_statements()

    def parse_statements(self):
        statements = []
        while True:
            token = self.tokenizer.peek_token()
            if not token or token[0] == 'END':
                break
            statements.append(self.parse_statement())
        return statements

    def parse_statement(self):
        token = self.tokenizer.peek_token()
        if not token:
            return None
        kind, value = token[:2]
        if kind == 'IDENTIFIER':
            return self.parse_assignment()
        elif kind == 'IF':
            return self.parse_if()
        elif kind == 'WHILE':
            return self.parse_while()
        elif kind == 'PRINT':
            return self.parse_print()
        raise SyntaxError(f"Unexpected token {kind}")

    def parse_assignment(self):
        variable = self.tokenizer.expect_token('IDENTIFIER')[1]
        self.tokenizer.expect_token('ASSIGN')
        expression = self.parse_expression()
        if self.tokenizer.peek_token()[0] == 'NEWLINE':
            self.tokenizer.next_token()  # Consume newline
        return AssignNode(variable, expression)

    def parse_if(self):
        self.tokenizer.expect_token('IF')
        condition = self.parse_expression()
        self.tokenizer.expect_token('THEN')
        then_body = self.parse_statements()
        else_body = []
        if self.tokenizer.peek_token()[0] == 'ELSE':
            self.tokenizer.next_token()
            else_body = self.parse_statements()
        self.tokenizer.expect_token('END')
        if self.tokenizer.peek_token()[0] == 'NEWLINE':
            self.tokenizer.next_token()  # Consume newline
        return IfNode(condition, then_body, else_body)

    def parse_while(self):
        self.tokenizer.expect_token('WHILE')
        condition = self.parse_expression()
        self.tokenizer.expect_token('DO')
        body = self.parse_statements()
        self.tokenizer.expect_token('END')
        if self.tokenizer.peek_token()[0] == 'NEWLINE':
            self.tokenizer.next_token()  # Consume newline
        return WhileNode(condition, body)

    def parse_print(self):
        self.tokenizer.expect_token('PRINT')
        expression = self.parse_expression()
        if self.tokenizer.peek_token()[0] == 'NEWLINE':
            self.tokenizer.next_token()  # Consume newline
        return PrintNode(expression)

    def parse_expression(self):
        left = self.parse_term()
        while self.tokenizer.peek_token() and self.tokenizer.peek_token()[0] in ('PLUS', 'MINUS'):
            op = self.tokenizer.next_token()[1]
            right = self.parse_term()
            left = BinaryOpNode(left, op, right)
        return left

    def parse_term(self):
        left = self.parse_factor()
        while self.tokenizer.peek_token() and self.tokenizer.peek_token()[0] in ('MULTIPLY', 'DIVIDE'):
            op = self.tokenizer.next_token()[1]
            right = self.parse_factor()
            left = BinaryOpNode(left, op, right)
        return left

    def parse_factor(self):
        token = self.tokenizer.next_token()
        if token[0] == 'NUMBER':
            return NumberNode(int(token[1]))
        elif token[0] == 'IDENTIFIER':
            return VariableNode(token[1])
        elif token[0] == 'LPAREN':
            expression = self.parse_expression()
            self.tokenizer.expect_token('RPAREN')
            return expression
        raise SyntaxError(f"Unexpected token {token[0]}")
```

### Step 4: Develop the Interpreter

The interpreter will execute the AST.

```python
class Interpreter:
    def __init__(self, ast):
        self.ast = ast
        self.variables = {}

    def execute(self):
        self.execute_statements(self.ast)

    def execute_statements(self, statements):
        for statement in statements:
            self.execute_statement(statement)

    def execute_statement(self, statement):
        if isinstance(statement, AssignNode):
            value = self.evaluate_expression(statement.expression)
            self.variables[statement.variable] = value
        elif isinstance(statement, PrintNode):
            value = self.evaluate_expression(statement.expression)
            print(value)
        elif isinstance(statement, IfNode):
            condition = self.evaluate_expression(statement.condition)
            if condition:
                self.execute_statements(statement.then_body)
            else:
                self.execute_statements(statement.else_body)
        elif isinstance(statement, WhileNode):
            while self.evaluate_expression(statement.condition):
                self.execute_statements(statement.body)

    def evaluate_expression(self, expression):
        if isinstance(expression, NumberNode):
            return expression.value
        elif isinstance(expression, VariableNode):
            return self.variables.get(expression.name, 0)
        elif isinstance(expression, BinaryOpNode):
            left = self.evaluate_expression(expression.left)
            right = self.evaluate_expression(expression.right)
            if expression.op == '+':
                return left + right
            elif expression.op == '-':
                return left - right
            elif expression.op == '*':
                return left * right
            elif expression.op == '/':
                return left / right
        raise RuntimeError(f"Unknown expression type {type(expression)}")
```

### Step 5: Putting it all together

Let's create a function to compile and execute the pseudo code.

```python
def run_pseudo_code(code):
