Example of using Date-fns with interactive calendar:
```jsx
import React from 'react';
import { format, startOfMonth, endOfMonth, startOfWeek, endOfWeek, addDays, isSameMonth, isSameDay } from 'date-fns';

const renderCells = (currentMonth, reservations) => {
  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(monthStart);
  const startDate = startOfWeek(monthStart);
  const endDate = endOfWeek(monthEnd);

  const rows = [];
  let days = [];
  let day = startDate;

  while (day <= endDate) {
    for (let i = 0; i < 7; i++) {
      const formattedDate = format(day, 'd');

      days.push(
        <div className={`col cell ${!isSameMonth(day, monthStart) ? "disabled" : isSameDay(day, new Date()) ? "selected" : ""}`} key={day}>
          <span className="number">{formattedDate}</span>
          <span className="bg">{formattedDate}</span>
        </div>
      );
      day = addDays(day, 1);
    }
    rows.push(
      <div key={day} className="row">
        {days}
      </div>
    );
    days = [];
  }
  return <div className="body">{rows}</div>;
};

const Dashboard = ({ reservations }) => {
    const currentMonth = new Date();
    return (
        <div>
            <header>
                <div> {format(currentMonth, 'MMMM yyyy')} </div>
            </header>
            <div>
                {renderCells(currentMonth, reservations)}
            </div>
        </div>
    );
};

export default Dashboard;
```

