      // Define a function to calculate the sum of digits for a single integer
      function digitSum(n) {
        // Handle negative integers by ignoring the negative sign and treating the integer as positive
        n = Math.abs(n);

        // Convert the integer to a string and split it into an array
        let digits = n.toString().split('');

        // Initialize a sum variable
        let sum = 0;

        // Loop through the digits array and add each digit to the sum
        for (let I = 0; I < digits.length; i++) {
          // Check if the current character is a number
          if (!isNaN(digits[i])) {
            sum += parseInt(digits[i], 10);
          } else {
            // If not, return an error message
            throw new Error("Invalid input. Please enter one or more positive integers, separated by commas.");
          }
        }

        // Return the sum
        return sum;
      }

      // Handle form submission
      document.querySelector('form').addEventListener('submit', function(event) {
        // Prevent the default form submission behavior
        event.preventDefault();

        // Get the input value and split it by commas
        let input = document.querySelector('#input').value;
        let nums = input.split(',').map(num => parseInt(num.trim()));

        // Create a results string to display the sum of digits for each integer
