// Node class for creating new nodes
class Node {
  int value;
  Node leftChild;
  Node rightChild;

  Node(int value) {
    this.value = value;
    leftChild = null;
    rightChild = null;
  }
}

// BinarySearchTree class for performing search, insert, and delete operations
class BinarySearchTree {
  Node root;

  BinarySearchTree() {
    root = null;
  }

  void insert(int value) {
    root = insertHelper(root, value);
  }

  Node insertHelper(Node root, int value) {
    if (root == null) {
      root = new Node(value);
      return root;
    }

    if (value < root.value) {
      root.leftChild = insertHelper(root.leftChild, value);
    } else if (value > root.value) {
      root.rightChild = insertHelper(root.rightChild, value);
    } 

    return root;
  }

  void search(int value) {
    searchHelper(root, value);
  }

  void searchHelper(Node root, int value) {
    if (root != null) {
      if (root.value == value) {
        System.out.println("Node found.");
      } else if (value < root.value) {
        searchHelper(root.leftChild, value);
      } else {
        searchHelper(root.rightChild, value);
      }
    } else {
      System.out.println("Node not found.");
    }
  }

  void delete(int value) {
    root = deleteHelper(root, value);
  }

  Node deleteHelper(Node root, int value) {
    if (root == null) {
      return root;
    }

    if (value < root.value) {
      root.leftChild = deleteHelper(root.leftChild, value);
    } else if (value > root.value) {
      root.rightChild = deleteHelper(root.rightChild, value);
    } else {
      if (root.leftChild == null) {
        return root.rightChild;
      } else if (root.rightChild == null) {
        return root.leftChild;
      }

      root.value = minValue(root.rightChild);

      root.rightChild = deleteHelper(root.rightChild, root.value);
    }

    return root;
  }

  int minValue(Node root) {
    int min = root.value;

    while (root.leftChild != null) {
      min = root.leftChild.value;
      root = root.leftChild;
    }

    return min;
  }

  void breadthFirstSearch() {
    int height = getHeight(root);

    for (int I = 1; I <= height; i++) {
      levelOrderTraversal(root, i);
    }
  }

  void levelOrderTraversal(Node root, int level) {
    if (root == null) {
      return;
    }

    if (level == 1) {
      System.out.print(root.value + " ");
    } else if (level > 1) {
      levelOrderTraversal(root.leftChild, level - 1);
      levelOrderTraversal(root.rightChild, level - 1);
    }
