Creating a sophisticated web TODO application with the specified features involves several steps, including frontend and backend development, along with deployment. Below is a detailed guide on how to develop and deploy this application:

### Tech Stack
1. **Frontend**: React.js for the UI, styled-components for styling (to achieve neumorphism design).
2. **Backend**: Node.js with Express.js for the server, and a simple in-memory storage or a database like MongoDB.
3. **Deployment**: Using tools like nginx for reverse-proxy and serving static files, Docker for containerization.

### Directory Structure
```
my-todo-app/
│
├── backend/
│   ├── package.json
│   ├── server.js
│   └── routes/
│       └── todoRoutes.js
│
├── frontend/
│   ├── package.json
│   ├── public/
│   ├── src/
│       ├── index.js
│       ├── App.js
│       ├── components/
│           ├── TodoList.js
│           ├── TodoItem.js
│           ├── AddTodo.js
│           └── styles/
│               └── neumorphism.js
│
├── docker-compose.yml
└── nginx/
    ├── nginx.conf
    └── Dockerfile
```

### Step 1: Setting Up the Backend
```javascript
// backend/package.json
{
  "name": "todo-backend",
  "version": "1.0.0",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^4.17.1",
    "cors": "^2.8.5"
  }
}

// backend/server.js
const express = require('express');
const cors = require('cors');
const app = express();
const port4500 = 4500;
const port7000 = 7000;
const todoRoutes = require('./routes/todoRoutes');

app.use(cors());
app.use(express.json());
app.use('/api/todos', todoRoutes);

app.listen(port4500, () => console.log(`Server running on port ${port4500}`));
app.listen(port7000, () => console.log(`Server running on port ${port7000}`));

// backend/routes/todoRoutes.js
const express = require('express');
const router = express.Router();
let todos = [];

router.get('/', (req, res) => {
  res.json(todos);
});

router.post('/', (req, res) => {
  const newTodo = { id: Date.now(), text: req.body.text };
  todos.push(newTodo);
  res.status(201).json(newTodo);
});

router.delete('/:id', (req, res) => {
  todos = todos.filter(todo => todo.id !== Number(req.params.id));
  res.status(204).send();
});

module.exports = router;
```

### Step 2: Setting Up the Frontend
```javascript
// frontend/package.json
{
  "name": "todo-frontend",
  "version": "1.0.0",
  "private": true,
  "dependencies": {
    "react": "^17.0.2",
    "react-dom": "^17.0.2",
    "react-scripts": "4.0.3",
    "styled-components": "^5.3.0"
  },
  "scripts": {
    "start": "react-scripts start",
    "build": "react-scripts build",
    "test": "react-scripts test",
    "eject": "react-scripts eject"
  }
}

// frontend/src/index.js
import React from 'react';
import ReactDOM from 'react-dom';
import App from './App';
import './index.css';

ReactDOM.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
  document.getElementById('root')
);

// frontend/src/App.js
import React, { useState, useEffect } from 'react';
import styled from 'styled-components';
import TodoList from './components/TodoList';
import AddTodo from './components/AddTodo';
import { neumorphismBoxShadow } from './components/styles/neumorphism';

const Container = styled.div`
  width: 90%;
  max-width: 600px;
  margin: 50px auto;
  box-shadow: ${neumorphismBoxShadow};
  padding: 20px;
`;

function App() {
  const [todos, setTodos] = useState([]);

  useEffect(() => {
    fetch('http://localhost:4500/api/todos')
      .then(response => response.json())
      .then(data => setTodos(data));
  }, []);

  const addTodo = text => {
    fetch('http://localhost:4500/api/todos', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text })
    })
    .then(response => response.json())
    .then(newTodo => setTodos([...todos, newTodo]));
  };

  const deleteTodo = id => {
    fetch(`http://localhost:4500/api/todos/${id}`, { method: 'DELETE' })
      .then(() => setTodos(todos.filter(todo => todo.id !== id)));
  };

  return (
    <Container>
      <h1>TODO List</h1>
      <AddTodo addTodo={addTodo} />
      <TodoList todos={todos} deleteTodo={deleteTodo} />
    </Container>
  );
}

export default App;

// frontend/src/components/TodoList.js
import React from 'react';
import TodoItem from './TodoItem';

const TodoList = ({ todos, deleteTodo }) => {
  return (
    <div>
      {todos.map(todo => (
        <TodoItem key={todo.id} todo={todo} deleteTodo={deleteTodo} />
      ))}
    </div>
  );
}

export default TodoList;

