        if (root == null) {
            root = new Node(data);
            return root;
        }

        if (data < root.data) {
            root.left = insertNodeRec(root.left, data);
        } else if (data > root.data) {
            root.right = insertNodeRec(root.right, data);
        }

        return root;
    }

    // Method to traverse the BST using breadth-first search
    void breadthFirstSearch() {
        if (root == null) {
            return;
        }

