To create and implement a comprehensive Smart City Information System that meets the specified requirements, I'll break down the solution into multiple sections: Minimum Spanning Tree (MST) for connectivity optimization, robust home automation systems, and stringent network security protocols integrated within a user-friendly administration interface. All solutions will be coded in Java.

### 1. Network Optimization using MST

We’ll use Kruskal's Algorithm to find the Minimum Spanning Tree for economically efficient inter-city connectivity.

```java
import java.util.*;

class Edge implements Comparable<Edge> {
    int src, dest, cost;
    public Edge(int src, int dest, int cost) {
        this.src = src;
        this.dest = dest;
        this.cost = cost;
    }
    public int compareTo(Edge other) {
        return this.cost - other.cost;
    }
}

class UnionFind {
    private int[] parent, rank;
    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) parent[i] = i;
    }
    public int find(int p) {
        if (p != parent[p]) parent[p] = find(parent[p]);
        return parent[p];
    }
    public void union(int p, int q) {
        int rootP = find(p), rootQ = find(q);
        if (rootP != rootQ) {
            if (rank[rootP] > rank[rootQ]) parent[rootQ] = rootP;
            else if (rank[rootP] < rank[rootQ]) parent[rootP] = rootQ;
            else {
                parent[rootQ] = rootP;
                rank[rootP]++;
            }
        }
    }
}

public class SmartCityNetwork {
    private static final Map<String, Integer> cityIndex = new HashMap<>();
    static {
        cityIndex.put("New York", 0);
        cityIndex.put("London", 1);
        cityIndex.put("Beijing", 2);
        cityIndex.put("Sydney", 3);
        cityIndex.put("Berlin", 4);
        cityIndex.put("Tokyo", 5);
    }

    private static List<Edge> edges = Arrays.asList(
        new Edge(cityIndex.get("New York"), cityIndex.get("London"), 10),
        new Edge(cityIndex.get("New York"), cityIndex.get("Beijing"), 60),
        new Edge(cityIndex.get("New York"), cityIndex.get("Sydney"), 70),
        new Edge(cityIndex.get("New York"), cityIndex.get("Berlin"), 30),
        new Edge(cityIndex.get("New York"), cityIndex.get("Tokyo"), 50),
        new Edge(cityIndex.get("London"), cityIndex.get("Beijing"), 20),
        new Edge(cityIndex.get("London"), cityIndex.get("Sydney"), 30),
        new Edge(cityIndex.get("London"), cityIndex.get("Berlin"), 10),
        new Edge(cityIndex.get("London"), cityIndex.get("Tokyo"), 30),
        new Edge(cityIndex.get("Beijing"), cityIndex.get("Sydney"), 10),
        new Edge(cityIndex.get("Beijing"), cityIndex.get("Berlin"), 40),
        new Edge(cityIndex.get("Beijing"), cityIndex.get("Tokyo"), 20),
        new Edge(cityIndex.get("Sydney"), cityIndex.get("Berlin"), 60),
        new Edge(cityIndex.get("Sydney"), cityIndex.get("Tokyo"), 30),
        new Edge(cityIndex.get("Berlin"), cityIndex.get("Tokyo"), 10)
    );

    public static List<Edge> getMinimumSpanningTree(int numberOfCities) {
        Collections.sort(edges);
        UnionFind uf = new UnionFind(numberOfCities);
        List<Edge> mst = new ArrayList<>();

        for (Edge edge : edges) {
            if (uf.find(edge.src) != uf.find(edge.dest)) {
                mst.add(edge);
                uf.union(edge.src, edge.dest);
            }
        }
        return mst;
    }

