```swift
func fib(_ n: Int) -> Int {
    if n < 0 {
        fatalError("n should be greater than or equal to 0")
    }
    if n == 0 {
        return 0
    }
    if n == 1 {
        return 1
    }
    return fib(n - 1) + fib(n - 2)
