Here is a simple python program that takes an integer n and returns the factorial of that number using recursion.

```python
def factorial(n):
    # Base case: 1! = 1
    if n == 1:
        return 1
    # Recursive case: n! = n * (n-1)!
    else:
        return n * factorial(n-1)
```
This `factorial(n)` function works by recursively calling itself with the argument `n-1`, until it gets to `1`. At each step, it multiplies the current `n` by the result of the recursive call. 

Do note that factorial is not defined for negative numbers and this will cause infinite recursion if a non-positive integer is used as input. So, in a production environment, please make sure to validate the input.

#include<iostream>
using namespace std;

bool isPowerOfTwo(int number){
   if(number==0){  
      return false;  
   }    
   return ((number & (-number)) == number);       
}

int main(){
   int num;
   cout<<"Enter a number: ";
   cin>>num;
   if(isPowerOfTwo(num)){
      cout<<num<<" is a power of 2";
   }
   else{
      cout<<num<<" is not a power of 2";   
   }
   return 0;
}

