#include <iostream>
#include <cstring>
using namespace std;

void printLPS(string str, int **dp, int i, int j){ // to print the longest palindromic subsequence
    if(i > j) return; // base case
    if(i == j){ // if there's only one character
        cout << str[i];
        return;
    }
    if(str[i] == str[j]){ // if the first and last characters are same
        cout << str[i];
        printLPS(str, dp, i+1, j-1); // recursive call for the substring excluding first and last characters
        cout << str[j];
    }else if(dp[i+1][j] > dp[i][j-1]){ // if the length of LPS in substring (i+1,j) > substring (i,j-1)
        printLPS(str, dp, i+1, j); // recursive call for the substring (i+1,j)
    }else{
        printLPS(str, dp, i, j-1); // recursive call for the substring (i,j-1)
    }
}

void longestPalindrome(string str){
    int n = str.length();
    int dp[n][n];

    // initializing diagonal elements to 1
    for(int i=0;i<n;i++) dp[i][i] = 1;

    // for lengths greater than 1
    for(int len=2;len<=n;len++){
        for(int i=0;i<n-len+1;i++){
            int j = i+len-1;
            if(str[i] == str[j] && len==2){ // if there are only 2 same characters
                dp[i][j] = 2;
            }else if(str[i] == str[j]){ // if first and last characters are same
                dp[i][j] = 2 + dp[i+1][j-1];
            }else{ // if first and last characters are not same
                dp[i][j] = max(dp[i][j-1], dp[i+1][j]);
            }
        }
    }

    cout << "Length of Longest Palindromic Subsequence: " << dp[0][n-1] << endl;
    cout << "Longest Palindromic Subsequence: ";
    printLPS(str, dp, 0, n-1);
}

int main(){
    string str;
    cout << "Enter a string: ";
    cin >> str;

    longestPalindrome(str);
    return 0;
}
```

