JavaScript for the navigation buttons:

```
var slider = document.getElementById('slider');
var sliderImages = slider.querySelector('.slider-images');
var images = sliderImages.getElementsByTagName('img');
var prevButton = slider.querySelector('#slider-prev');
var nextButton = slider.querySelector('#slider-next');
var currentImage = 0;

function slideImages() {
  currentImage++;
  if(currentImage >= images.length) {
    currentImage = 0;
  }
  var translateX = -100 * currentImage;
  sliderImages.style.transform = 'translateX(' + translateX + '%)';
}

prevButton.addEventListener('click', function() {
  currentImage--;
  if(currentImage < 0) {
    currentImage = images.length - 1;
  }
  var translateX = -100 * currentImage;
  sliderImages.style.transform = 'translateX(' + translateX + '%)';
});

nextButton.addEventListener('click', function() {
  slideImages();
});

setInterval(slideImages, 5000);
```

In this example, we added two buttons with the IDs "slider-prev" and "slider-next", and used JavaScript to add event listeners to them. When the user clicks the "Prev" button, it goes back to the previous image in the slideshow. When the user clicks the "Next" button, it goes to the next image as it would with the automatic slideshow.

